parameters.jsonBody:
={{ {
  "system_instruction": { 
    "parts": [{ 
      "text": $('Load Prompts').item.json.understand_intent_prompt + "\n\nCRITICAL SEARCH RULE: Search for the real template image. In 'template_reference_url', supply a direct image URL ending in .jpg, .png, or from a known meme CDN (e.g. i.imgflip.com, i.kym-cdn.com, wikimedia.org). If only webpage URLs are returned, set it to null.\nRespond with ONLY valid JSON, no markdown code fences, no extra commentary." 
    }] 
  },
  "contents": [{
    "parts": [
      { "text": "user_text: " + $json.user_text + "\nhas_reference_image: " + (!!$json.reference_image_b64) },
      $json.reference_image_b64 ? { "inline_data": { "mime_type": "image/jpeg", "data": $json.reference_image_b64 } } : null
    ].filter(p => p !== null)
  }],
  "tools": [{ "googleSearch": {} }],
  "generationConfig": {
    "thinkingConfig": { "thinkingLevel": "low" },
    "maxOutputTokens": 2048
  }
} }}

