const rawText = $json.candidates[0].content.parts[0].text;
const cleanText = rawText.replace(/```json|```/g, '').trim();
const parsed = JSON.parse(cleanText);

return {
  json: {
    ...$json,
    image_edit_prompt: parsed.image_edit_prompt,
    engineer_reasoning: parsed.reasoning
  }
};

const state = $('Parse Engineered Prompt').item.json;

const parts = $json.candidates[0].content.parts;
const imagePart = parts.find(p => p.inline_data || p.inlineData);

const imageData = imagePart?.inline_data?.data || imagePart?.inlineData?.data;

if (!imageData) {
  throw new Error('No image data found in generation response. Raw parts: ' + JSON.stringify(parts));
}

return [{ json: { ...state, generated_image_b64: imageData } }];

